// Cool tones palette for a fractal spiral
const SKY = '#1a2a4a'; // Dark blue sky
const GROUND = '#3a5a7a'; // Deep blue ground
const ACCENT = '#5a8abf'; // Light blue accent
const SHADOW = '#0a1a3a'; // Darker shadow
const HIGHLIGHT = '#8ab4d8'; // Lighter highlight

// Draw background
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw spiral with cool tones
function drawSpiral(x, y, r, depth) {
    if (depth > 0) {
        // Draw spiral arms
        ctx.fillStyle = ACCENT;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + r * Math.cos(depth), y - r * Math.sin(depth));
        ctx.strokeStyle = ACCENT;
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.stroke();

        // Recursive calls for inner spiral arms
        drawSpiral(x + r * Math.cos(depth), y - r * Math.sin(depth), r * 0.8, depth - 1);
        drawSpiral(x - r * Math.cos(depth), y + r * Math.sin(depth), r * 0.8, depth - 1);
    }
}

// Draw main spiral
drawSpiral(200, 200, 150, 8);

// Add some subtle gradient effect
ctx.fillStyle = HIGHLIGHT;
for (let i = 0; i < 10; i++) {
    const angle = (i / 10) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 160;
    const y = 200 - Math.sin(angle) * 160;
    const radius = 10 + i * 5;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
}

// Add some more subtle details
ctx.fillStyle = SHADOW;
for (let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 120;
    const y = 200 - Math.sin(angle) * 120;
    const radius = 5 + i * 3;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
}

// Add a few more spiral arms to fill space
ctx.fillStyle = ACCENT;
for (let i = 0; i < 4; i++) {
    const angle = (i / 4) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 100;
    const y = 200 - Math.sin(angle) * 100;
    const r = 80 + i * 20;
    drawSpiral(x, y, r, 6);
}

