// Draw jellyfish body
const cx = 200;
const cy = 180;
const radius = 40;

// Main body
ctx.fillStyle = '#ffd166';
ctx.beginPath();
ctx.arc(cx, cy, radius, 0, Math.PI * 2);
ctx.fill();

// Tentacles
ctx.fillStyle = '#ffd166';
for(let i = 0; i < 8; i++) {
    const angle = (i / 8) * Math.PI * 2;
    const x1 = cx + Math.cos(angle) * (radius + 20);
    const y1 = cy + Math.sin(angle) * (radius + 20);
    const x2 = cx + Math.cos(angle) * (radius + 80);
    const y2 = cy + Math.sin(angle) * (radius + 80);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineWidth = 8;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#ffd166';
    ctx.stroke();

    // Tentacle tips
    ctx.fillStyle = '#ffaa55';
    ctx.beginPath();
    ctx.arc(x2, y2, 15, 0, Math.PI * 2);
    ctx.fill();
}

