// Draw spiral shell
ctx.fillStyle = '#8B4513';
ctx.beginPath();
let r = 10;
for (let i = 0; i < 20; i++) {
    const angle = i * 0.5;
    const x = 200 + Math.cos(angle) * r;
    const y = 250 + Math.sin(angle) * r;
    if (i === 0) {
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }
    r += 2;
}
ctx.closePath();
ctx.fill();

// Draw spiral shell details
