    const angle = i * 0.5;
    const r = 10 + i * 2;
    const x = 200 + Math.cos(angle) * r;
    const y = 250 + Math.sin(angle) * r;
    if (i === 0) {
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }
}
ctx.stroke();

